<template><OperationsFrame title="字典管理">
 <div class="operations-catalog"><section><el-form :inline="true"><el-form-item><el-input v-model="query.keyword" placeholder="字典名称 / 编码" clearable @keyup.enter="search" /></el-form-item><el-form-item><el-button type="primary" icon="Search" @click="search">搜索</el-button></el-form-item></el-form><div class="operations-toolbar"><el-button type="primary" plain icon="Plus" @click="editType()">新增字典</el-button><el-button icon="Refresh" @click="refresh">刷新缓存</el-button></div>
 <el-table :data="rows" v-loading="loading" highlight-current-row @current-change="select" row-key="dictId"><el-table-column prop="dictName" label="字典名称" min-width="150" /><el-table-column prop="dictType" label="编码" min-width="180" show-overflow-tooltip /><el-table-column label="操作" width="120"><template #default="{row}"><el-button v-if="!row.builtin" link type="primary" @click.stop="editType(row)">修改</el-button><el-button v-if="!row.builtin" link type="danger" @click.stop="removeType(row)">删除</el-button><el-tag v-else type="info">内置</el-tag></template></el-table-column></el-table>
 <pagination v-show="total>0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load" :page-sizes="[10,20,50]" layout="prev, pager, next" />
 </section><section><div class="operations-toolbar"><strong>{{selected?.dictName||'请选择字典'}}</strong><el-button v-if="selected&&!selected.builtin" type="primary" plain icon="Plus" @click="editItem()">新增数据</el-button><el-button v-if="selected" icon="Refresh" @click="loadItems">刷新</el-button></div>
 <el-table :data="items" v-loading="itemLoading"><el-table-column prop="dictSort" label="排序" width="75" /><el-table-column prop="dictLabel" label="显示名称" min-width="150" /><el-table-column prop="remark" label="使用页面" min-width="150" /><el-table-column prop="dictValue" label="数据值" min-width="140" /><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status==='0'?'success':'info'">{{row.status==='0'?'正常':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="130"><template #default="{row}"><el-button v-if="!selected?.dictType.startsWith('sys_')" link type="primary" @click="editItem(row)">修改</el-button><el-button v-if="!selected?.builtin" link type="danger" @click="removeItem(row)">删除</el-button></template></el-table-column></el-table>
 <pagination v-show="itemTotal>0" :total="itemTotal" v-model:page="itemQuery.pageNum" v-model:limit="itemQuery.pageSize" @pagination="loadItems" />
 <p v-if="selected?.builtin" class="operations-caption">内置编码固定。停用后保留历史显示名称。</p>
 </section></div>
 <el-dialog v-model="open" :title="editingItem?(form.dictCode?'修改字典数据':'新增字典数据'):(form.dictId?'修改字典':'新增字典')" width="570px" class="operations-dialog"><el-form ref="formRef" :model="form" label-width="90px"><template v-if="editingItem"><el-form-item label="显示名称" prop="dictLabel" :rules="required"><el-input v-model="form.dictLabel" maxlength="100" /></el-form-item><el-form-item label="数据值" prop="dictValue" :rules="required"><el-input v-model="form.dictValue" :disabled="!!selected?.builtin" maxlength="100" /></el-form-item><el-form-item label="排序"><el-input-number v-model="form.dictSort" :min="0" :max="9999" /></el-form-item></template><template v-else><el-form-item label="字典名称" prop="dictName" :rules="required"><el-input v-model="form.dictName" maxlength="100" /></el-form-item><el-form-item label="字典编码" prop="dictType" :rules="required"><el-input v-model="form.dictType" :disabled="!!form.dictId" placeholder="drilling_" maxlength="100" /></el-form-item></template><el-form-item label="状态"><el-radio-group v-model="form.status" ><el-radio value="0">正常</el-radio><el-radio value="1">停用</el-radio></el-radio-group></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" maxlength="500" /></el-form-item></el-form><template #footer><el-button @click="open=false">取 消</el-button><el-button type="primary" :loading="saving" @click="save">确 定</el-button></template></el-dialog>
</OperationsFrame></template>
<script setup>
import {ref,reactive} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import OperationsFrame from './OperationsFrame.vue';import {useOperations} from './useOperations';import {listOperation,createOperation,updateOperation,removeOperation,executeOperation} from '@/api/operations';
const {rows,total,loading,query,load,search}=useOperations('dictionaries',{keyword:''});const selected=ref(null),items=ref([]),itemTotal=ref(0),itemLoading=ref(false),itemQuery=reactive({pageNum:1,pageSize:20}),open=ref(false),editingItem=ref(false),saving=ref(false),form=reactive({}),formRef=ref();const required=[{required:true,message:'此项不能为空',trigger:'blur'}];let itemRequest=0
async function select(row){selected.value=row;itemQuery.pageNum=1;await loadItems()}
async function loadItems(){const request=++itemRequest;if(!selected.value){items.value=[];itemTotal.value=0;return}itemLoading.value=true;try{const r=await listOperation(`dictionaries/${selected.value.dictId}/items`,itemQuery);if(request===itemRequest){items.value=r.rows;itemTotal.value=r.total}}catch{}finally{if(request===itemRequest)itemLoading.value=false}}
function formOpen(value,isItem){editingItem.value=isItem;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,value);open.value=true;formRef.value?.clearValidate()}
function editType(row){formOpen(row?{...row}:{dictName:'',dictType:'drilling_',status:'0',remark:''},false)}
function editItem(row){formOpen(row?{...row}:{dictLabel:'',dictValue:'',dictSort:0,status:'0',remark:''},true)}
async function save(){if(!await formRef.value.validate().catch(()=>false))return;saving.value=true;try{if(editingItem.value){if(form.dictCode)await updateOperation('dictionary-items',form.dictCode,form);else await createOperation(`dictionaries/${selected.value.dictId}/items`,form);await loadItems()}else{if(form.dictId)await updateOperation('dictionaries',form.dictId,form);else await createOperation('dictionaries',form);await load();selected.value=null;items.value=[];itemTotal.value=0}open.value=false;ElMessage.success('字典已保存')}catch{}finally{saving.value=false}}
async function removeType(row){try{await ElMessageBox.confirm(`删除字典 ${row.dictName}？`,'删除字典',{type:'warning'});await removeOperation('dictionaries',row.dictId);selected.value=null;items.value=[];itemTotal.value=0;await load()}catch{}}
async function removeItem(row){try{await ElMessageBox.confirm(`删除数据 ${row.dictLabel}？`,'删除字典数据',{type:'warning'});await removeOperation('dictionary-items',row.dictCode);await loadItems()}catch{}}
async function refresh(){try{await executeOperation('dictionaries/refresh');await load();ElMessage.success('字典缓存已刷新')}catch{}}
</script>
